import { Schema } from "effect";
import {
  RichTextDocument,
  RichTextLink,
  RichTextVariable,
} from "@/lib/rich-text/schema";

export const EmailImageUrl = RichTextLink.check(
  Schema.isPattern(/^https:\/\//),
).annotate({ identifier: "EmailImageUrl" });
export const EmailColor = Schema.String.check(
  Schema.isPattern(/^#[0-9a-fA-F]{6}$/),
).annotate({ identifier: "EmailColor" });
export const EmailAlignment = Schema.Literals([
  "left",
  "center",
  "right",
]).annotate({ identifier: "EmailAlignment" });
export const EmailFont = Schema.Literals(["sans", "serif", "mono"]).annotate({
  identifier: "EmailFont",
});
const spacing = Schema.Int.check(Schema.isBetween({ minimum: 0, maximum: 96 }));
const common = {
  id: Schema.NonEmptyString.check(Schema.isMaxLength(80)),
  alignment: EmailAlignment,
  paddingTop: spacing,
  paddingBottom: spacing,
};
export const EmailDestination = Schema.Union([
  Schema.Struct({ type: Schema.Literal("url"), url: RichTextLink }),
  Schema.Struct({
    type: Schema.Literal("variable"),
    key: RichTextVariable.fields.key,
  }),
]).annotate({ identifier: "EmailDestination" });
export const EmailElement = Schema.Union([
  Schema.Struct({
    ...common,
    type: Schema.Literal("text"),
    content: RichTextDocument,
  }),
  Schema.Struct({
    ...common,
    type: Schema.Literal("button"),
    label: Schema.String.check(Schema.isMaxLength(200)),
    destination: EmailDestination,
  }),
  Schema.Struct({
    ...common,
    type: Schema.Literal("code"),
    variable: RichTextVariable.fields.key,
  }),
  Schema.Struct({
    ...common,
    type: Schema.Literals(["logo", "image"]),
    src: EmailImageUrl,
    alt: Schema.String.check(Schema.isMaxLength(200)),
    width: Schema.Int.check(Schema.isBetween({ minimum: 32, maximum: 560 })),
  }),
  Schema.Struct({ ...common, type: Schema.Literal("divider") }),
  Schema.Struct({ ...common, type: Schema.Literal("spacer"), height: spacing }),
]).annotate({ identifier: "EmailElement" });
const subject = Schema.String.check(
  Schema.isMaxLength(200),
  Schema.isPattern(/^[^\r\n]*$/),
);
export const EmailDocument = Schema.Struct({
  version: Schema.Literal(1),
  subject,
  preview: subject,
  appearance: Schema.Struct({
    background: EmailColor,
    surface: EmailColor,
    text: EmailColor,
    primary: EmailColor,
    primaryText: EmailColor,
    font: EmailFont,
    radius: Schema.Int.check(Schema.isBetween({ minimum: 0, maximum: 32 })),
  }),
  elements: Schema.Array(EmailElement).check(Schema.isMaxLength(40)),
})
  .check(
    Schema.makeFilter(
      (document) =>
        new Set(document.elements.map((element) => element.id)).size ===
        document.elements.length,
    ),
  )
  .annotate({ identifier: "EmailDocument" });
export const EmailRenderInput = Schema.Struct({
  document: EmailDocument,
  variables: Schema.Array(RichTextVariable),
  values: Schema.Record(Schema.String, Schema.String),
  requiredVariables: Schema.optional(Schema.Array(Schema.String)),
}).annotate({ identifier: "EmailRenderInput" });
export const EmailRenderResult = Schema.Struct({
  subject: Schema.String,
  html: Schema.String,
  text: Schema.String,
}).annotate({ identifier: "EmailRenderResult" });
export type EmailDocument = typeof EmailDocument.Type;
export type EmailElement = typeof EmailElement.Type;
export type EmailDestination = typeof EmailDestination.Type;
export type EmailRenderInput = typeof EmailRenderInput.Type;
export type EmailRenderResult = typeof EmailRenderResult.Type;

import { Schema } from "effect";
import {
  RichTextLink,
  type RichTextVariable,
  type RichTextDocument,
} from "@/lib/rich-text/schema";
import { richTextFromString } from "@/lib/rich-text/model";
import { EmailDocument, type EmailElement } from "./schema";

export const emailElementTypes = [
  "text",
  "button",
  "code",
  "logo",
  "image",
  "divider",
  "spacer",
] as const;
export type EmailElementType = (typeof emailElementTypes)[number];
export const newEmailElement = (
  type: EmailElementType,
  input: {
    id: string;
    text: string;
    button: string;
    imageAlt: string;
    codeVariable?: string;
    urlVariable?: string;
  },
): EmailElement => {
  const common = {
    id: input.id,
    alignment: "left",
    paddingTop: 8,
    paddingBottom: 8,
  } as const;
  switch (type) {
    case "text":
      return { ...common, type, content: richTextFromString(input.text) };
    case "button":
      return {
        ...common,
        type,
        label: input.button,
        destination: input.urlVariable
          ? { type: "variable", key: input.urlVariable }
          : { type: "url", url: "https://example.com" },
      };
    case "code":
      return { ...common, type, variable: input.codeVariable ?? "code" };
    case "logo":
    case "image":
      return {
        ...common,
        type,
        src: "https://krakstack.net/favicon.svg",
        alt: input.imageAlt,
        width: type === "logo" ? 48 : 160,
      };
    case "divider":
      return { ...common, type };
    case "spacer":
      return { ...common, type, height: 24 };
  }
};

export const interpolateEmailText = (
  text: string,
  values: Readonly<Record<string, string>>,
) =>
  text.replace(
    /\{\{([a-zA-Z][a-zA-Z0-9_.]*)\}\}/g,
    (token, key: string) => values[key] ?? token,
  );
/** Keep header templates as strings while editing variables as atomic rich-text nodes. */
export const richTextFromEmailText = (text: string): RichTextDocument => ({
  version: 1,
  blocks: [
    {
      type: "paragraph",
      content: text
        .split(/(\{\{[a-zA-Z][a-zA-Z0-9_.]*\}\})/g)
        .filter(Boolean)
        .map((part) =>
          /^\{\{[a-zA-Z][a-zA-Z0-9_.]*\}\}$/.test(part)
            ? { type: "variable", key: part.slice(2, -2) }
            : { type: "text", text: part },
        ),
    },
  ],
});
const textReferences = (text: string) =>
  [...text.matchAll(/\{\{([a-zA-Z][a-zA-Z0-9_.]*)\}\}/g)].map(
    (match) => match[1] ?? "",
  );
export const emailDocumentReferences = (document: EmailDocument) => [
  ...new Set([
    ...textReferences(document.subject),
    ...textReferences(document.preview),
    ...document.elements.flatMap((element) => {
      switch (element.type) {
        case "text":
          return element.content.blocks.flatMap((block) =>
            block.content.flatMap((inline) =>
              inline.type === "variable" ? [inline.key] : [],
            ),
          );
        case "code":
          return [element.variable];
        case "button":
          return [
            ...textReferences(element.label),
            ...(element.destination.type === "variable"
              ? [element.destination.key]
              : []),
          ];
        default:
          return [];
      }
    }),
  ]),
];

export type EmailDocumentIssue = {
  code:
    | "invalid-document"
    | "unknown-variable"
    | "missing-variable"
    | "invalid-url"
    | "missing-required-variable";
  key?: string;
};
export const validateEmailDocument = ({
  document,
  variables,
  values,
  requiredVariables = [],
}: {
  document: EmailDocument;
  variables: readonly RichTextVariable[];
  values?: Readonly<Record<string, string>>;
  requiredVariables?: readonly string[];
}): EmailDocumentIssue[] => {
  if (!Schema.is(EmailDocument)(document))
    return [{ code: "invalid-document" }];
  const references = emailDocumentReferences(document);
  const issues: EmailDocumentIssue[] = [];
  for (const key of references) {
    if (!variables.some((variable) => variable.key === key))
      issues.push({ code: "unknown-variable", key });
    if (values && !values[key]) issues.push({ code: "missing-variable", key });
  }
  for (const element of document.elements) {
    if (element.type === "button" && element.destination.type === "variable") {
      const key = element.destination.key;
      if (
        variables.find((variable) => variable.key === key)?.type !== "url" ||
        (values && !Schema.is(RichTextLink)(values[key]))
      )
        issues.push({ code: "invalid-url", key });
    }
  }
  for (const key of requiredVariables)
    if (
      !document.elements.some(
        (element) =>
          (element.type === "code" && element.variable === key) ||
          (element.type === "button" &&
            element.destination.type === "variable" &&
            element.destination.key === key) ||
          (element.type === "text" &&
            element.content.blocks.some((block) =>
              block.content.some(
                (inline) => inline.type === "variable" && inline.key === key,
              ),
            )),
      )
    )
      issues.push({ code: "missing-required-variable", key });
  return issues;
};

import { Effect, Schema } from "effect";
import { renderToStaticMarkup } from "react-dom/server";
import type { CSSProperties, ReactNode } from "react";
import {
  RichTextLink,
  type RichTextDocument,
  type RichTextInline,
} from "@/lib/rich-text/schema";
import { richTextPlainText } from "@/lib/rich-text/model";
import { EmailRenderInput } from "./schema";
import { interpolateEmailText, validateEmailDocument } from "./model";

export class EmailDocumentRenderError extends Schema.TaggedError<
  EmailDocumentRenderError,
  { readonly brand: unique symbol }
>()("EmailDocumentRenderError", { reason: Schema.String }) {}
const fonts = {
  sans: "Arial, Helvetica, sans-serif",
  serif: "Georgia, 'Times New Roman', serif",
  mono: "'Courier New', monospace",
};
const inline = (
  node: RichTextInline,
  values: Readonly<Record<string, string>>,
) => {
  let content: ReactNode = node.type === "text" ? node.text : values[node.key];
  if (node.marks?.bold) content = <strong>{content}</strong>;
  if (node.marks?.italic) content = <em>{content}</em>;
  if (node.marks?.underline) content = <u>{content}</u>;
  if (node.marks?.href)
    content = (
      <a href={node.marks.href} style={{ color: "inherit" }}>
        {content}
      </a>
    );
  return content;
};
const richContent = (
  value: RichTextDocument,
  values: Readonly<Record<string, string>>,
) =>
  value.blocks.flatMap((block, index) => {
    if (
      (block.type === "bullet" || block.type === "numbered") &&
      value.blocks[index - 1]?.type === block.type
    )
      return [];
    const content = block.content.map((node, key) => (
      <span key={key}>{inline(node, values)}</span>
    ));
    if (block.type === "heading")
      return (
        <h2
          key={index}
          style={{ margin: "0 0 12px", fontSize: 26, lineHeight: 1.25 }}
        >
          {content}
        </h2>
      );
    if (block.type === "bullet" || block.type === "numbered") {
      const List = block.type === "bullet" ? "ul" : "ol";
      const end = value.blocks.findIndex(
        (next, nextIndex) => nextIndex > index && next.type !== block.type,
      );
      const items = value.blocks.slice(index, end < 0 ? undefined : end);
      return (
        <List key={index} style={{ margin: "0 0 8px", paddingLeft: 24 }}>
          {items.map((item, itemIndex) => (
            <li key={itemIndex}>
              {item.content.map((node, key) => (
                <span key={key}>{inline(node, values)}</span>
              ))}
            </li>
          ))}
        </List>
      );
    }
    return (
      <p key={index} style={{ margin: "0 0 12px", minHeight: 20 }}>
        {content.length ? content : <br />}
      </p>
    );
  });

/** The same validated document produces HTML and plain text; no executable templates. */
export const renderEmailDocument = Effect.fn("EmailDocument.render")(function* (
  input: EmailRenderInput,
) {
  const decoded = yield* Schema.decodeEffect(EmailRenderInput)(input).pipe(
    Effect.mapError(
      () => new EmailDocumentRenderError({ reason: "invalid-document" }),
    ),
  );
  const issues = validateEmailDocument(decoded);
  if (issues.length)
    return yield* new EmailDocumentRenderError({
      reason: issues
        .map((issue) => `${issue.code}${issue.key ? `:${issue.key}` : ""}`)
        .join(", "),
    });
  const { document, values } = decoded;
  const theme = document.appearance;
  const interpolate = (value: string) => interpolateEmailText(value, values);
  const subject = interpolate(document.subject).replace(/[\r\n]/g, " ");
  const renderedElements = document.elements.map((element) => {
    let content: ReactNode;
    switch (element.type) {
      case "text":
        content = richContent(element.content, values);
        break;
      case "button": {
        const href =
          element.destination.type === "url"
            ? element.destination.url
            : values[element.destination.key];
        if (!Schema.is(RichTextLink)(href)) return null;
        content = (
          <table
            role="presentation"
            cellPadding={0}
            cellSpacing={0}
            style={{ display: "inline-table" }}
          >
            <tbody>
              <tr>
                <td
                  style={{
                    backgroundColor: theme.primary,
                    borderRadius: 6,
                    padding: "13px 24px",
                  }}
                >
                  <a
                    href={href}
                    style={{
                      color: theme.primaryText,
                      fontWeight: 600,
                      textDecoration: "none",
                      display: "inline-block",
                    }}
                  >
                    {interpolate(element.label)}
                  </a>
                </td>
              </tr>
            </tbody>
          </table>
        );
        break;
      }
      case "code":
        content = (
          <div
            style={{
              padding: "18px 24px",
              border: "1px solid #e5e7eb",
              borderRadius: 8,
              fontFamily: fonts.mono,
              fontSize: 32,
              letterSpacing: 6,
              fontWeight: 700,
            }}
          >
            {values[element.variable]}
          </div>
        );
        break;
      case "logo":
      case "image":
        content = (
          <img
            src={element.src}
            alt={element.alt}
            width={element.width}
            style={{
              maxWidth: "100%",
              height: "auto",
              display: "inline-block",
              border: 0,
            }}
          />
        );
        break;
      case "divider":
        content = (
          <hr
            style={{ border: 0, borderTop: "1px solid #e5e7eb", margin: 0 }}
          />
        );
        break;
      case "spacer":
        content = (
          <div
            style={{
              height: element.height,
              lineHeight: `${element.height}px`,
            }}
          >
            &nbsp;
          </div>
        );
        break;
    }
    return (
      <tr key={element.id}>
        <td
          style={{
            paddingTop: element.paddingTop,
            paddingBottom: element.paddingBottom,
            textAlign: element.alignment,
          }}
        >
          {content}
        </td>
      </tr>
    );
  });
  const bodyStyle: CSSProperties = {
    margin: 0,
    padding: 0,
    backgroundColor: theme.background,
    color: theme.text,
    fontFamily: fonts[theme.font],
  };
  const html = yield* Effect.try({
    try: () =>
      "<!DOCTYPE html>" +
      renderToStaticMarkup(
        <html>
          <head>
            <meta charSet="utf-8" />
            <meta
              name="viewport"
              content="width=device-width, initial-scale=1"
            />
            <title>{subject}</title>
          </head>
          <body style={bodyStyle}>
            <div
              style={{
                display: "none",
                maxHeight: 0,
                overflow: "hidden",
                opacity: 0,
              }}
            >
              {interpolate(document.preview)}
            </div>
            <table
              role="presentation"
              width="100%"
              cellPadding={0}
              cellSpacing={0}
              style={bodyStyle}
            >
              <tbody>
                <tr>
                  <td align="center" style={{ padding: "32px 12px" }}>
                    <table
                      role="presentation"
                      width="100%"
                      cellPadding={0}
                      cellSpacing={0}
                      style={{
                        maxWidth: 600,
                        backgroundColor: theme.surface,
                        borderRadius: theme.radius,
                      }}
                    >
                      <tbody>
                        <tr>
                          <td
                            style={{
                              padding: 32,
                              fontSize: 16,
                              lineHeight: 1.6,
                            }}
                          >
                            <table
                              role="presentation"
                              width="100%"
                              cellPadding={0}
                              cellSpacing={0}
                            >
                              <tbody>{renderedElements}</tbody>
                            </table>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </td>
                </tr>
              </tbody>
            </table>
          </body>
        </html>,
      ),
    catch: () => new EmailDocumentRenderError({ reason: "render-failed" }),
  });
  const text = document.elements
    .map((element) => {
      switch (element.type) {
        case "text":
          return richTextPlainText(element.content, values);
        case "button":
          return `${interpolate(element.label)}: ${element.destination.type === "url" ? element.destination.url : values[element.destination.key]}`;
        case "code":
          return values[element.variable];
        case "image":
        case "logo":
          return element.alt;
        case "divider":
          return "---";
        case "spacer":
          return "";
      }
    })
    .filter(Boolean)
    .join("\n\n");
  return { subject, html, text };
});
